[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Aid Alliance — Together We Respond</title>
  <meta name="description" content="A humanitarian nonprofit organization dedicated to disaster relief, emergency assistance, and community resilience worldwide." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Lora:wght@400;600&display=swap" rel="stylesheet" />
  <style>
    /* ── Reset & base ── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; font-size: 16px; }
    body {
      font-family: 'Inter', sans-serif;
      color: #1a1a1a;
      background: #fff;
      line-height: 1.6;
    }
    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    ul { list-style: none; }
    button { cursor: pointer; font-family: inherit; }

    /* ── Design tokens ── */
    :root {
      --red: #C41E3A;
      --red-dark: #a01830;
      --red-light: #f8e8eb;
      --navy: #1B3A5C;
      --navy-light: #eef2f7;
      --white: #ffffff;
      --gray-50: #f9fafb;
      --gray-100: #f3f4f6;
      --gray-200: #e5e7eb;
      --gray-400: #9ca3af;
      --gray-600: #4b5563;
      --gray-800: #1f2937;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.10);
      --shadow-md: 0 4px 16px rgba(0,0,0,.12);
      --shadow-lg: 0 10px 40px rgba(0,0,0,.14);
      --radius: 8px;
      --radius-lg: 16px;
      --max-w: 1200px;
    }

    /* ── Utility ── */
    .container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }
    .sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: var(--radius);
      font-weight: 600;
      font-size: 0.95rem;
      border: 2px solid transparent;
      transition: background .2s, color .2s, border-color .2s, transform .1s;
      white-space: nowrap;
    }
    .btn:active { transform: translateY(1px); }
    .btn-primary { background: var(--red); color: #fff; border-color: var(--red); }
    .btn-primary:hover { background: var(--red-dark); border-color: var(--red-dark); }
    .btn-outline-white { background: transparent; color: #fff; border-color: rgba(255,255,255,.7); }
    .btn-outline-white:hover { background: rgba(255,255,255,.12); border-color: #fff; }
    .btn-outline-red { background: transparent; color: var(--red); border-color: var(--red); }
    .btn-outline-red:hover { background: var(--red-light); }
    .btn-sm { padding: 10px 20px; font-size: 0.875rem; }

    .section-label {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--red);
      margin-bottom: 12px;
    }
    .section-heading {
      font-family: 'Lora', serif;
      font-size: clamp(1.6rem, 3vw, 2.4rem);
      color: var(--navy);
      line-height: 1.25;
      margin-bottom: 16px;
    }
    .section-subheading {
      font-size: 1.05rem;
      color: var(--gray-600);
      max-width: 600px;
      line-height: 1.7;
    }

    /* ── Utility bar ── */
    .utility-bar {
      background: var(--navy);
      color: rgba(255,255,255,.85);
      font-size: 0.8rem;
    }
    .utility-inner {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 20px;
      height: 36px;
    }
    .utility-bar a:hover { color: #fff; }

    /* ── Header ── */
    .site-header {
      background: #fff;
      border-bottom: 2px solid var(--gray-100);
      position: sticky;
      top: 0;
      z-index: 100;
      box-shadow: var(--shadow-sm);
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
      gap: 24px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-shrink: 0;
    }
    .logo-icon {
      width: 44px;
      height: 44px;
      background: var(--red);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #fff;
      font-size: 1.3rem;
      font-weight: 800;
    }
    .logo-text { line-height: 1.15; }
    .logo-name {
      font-weight: 800;
      font-size: 1rem;
      color: var(--navy);
    }
    .logo-tagline {
      font-size: 0.7rem;
      color: var(--gray-600);
      letter-spacing: .05em;
    }

    .main-nav { display: flex; align-items: center; gap: 4px; }
    .main-nav a {
      padding: 8px 14px;
      font-size: 0.9rem;
      font-weight: 500;
      color: var(--gray-800);
      border-radius: var(--radius);
      transition: background .15s, color .15s;
    }
    .main-nav a:hover { background: var(--gray-100); color: var(--navy); }
    .main-nav .donate-btn {
      background: var(--red);
      color: #fff;
      font-weight: 600;
      margin-left: 8px;
    }
    .main-nav .donate-btn:hover { background: var(--red-dark); }

    .hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      gap: 5px;
      background: none;
      border: none;
      padding: 8px;
      cursor: pointer;
      border-radius: var(--radius);
    }
    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--gray-800);
      border-radius: 2px;
      transition: transform .3s, opacity .2s;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .mobile-nav {
      display: none;
      flex-direction: column;
      background: #fff;
      border-top: 1px solid var(--gray-200);
      padding: 12px 24px 20px;
      gap: 2px;
    }
    .mobile-nav.open { display: flex; }
    .mobile-nav a {
      padding: 12px 8px;
      font-size: 1rem;
      font-weight: 500;
      color: var(--gray-800);
      border-bottom: 1px solid var(--gray-100);
    }
    .mobile-nav a:last-child { border-bottom: none; }
    .mobile-nav .mobile-donate {
      margin-top: 12px;
      background: var(--red);
      color: #fff;
      text-align: center;
      padding: 14px;
      border-radius: var(--radius);
      font-weight: 600;
      border-bottom: none;
    }

    /* ── Hero ── */
    .hero {
      position: relative;
      min-height: 600px;
      display: flex;
      align-items: center;
      overflow: hidden;
      background: linear-gradient(135deg, #0e1f33 0%, var(--navy) 45%, #8b1a28 100%);
    }
    .hero-bg {
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse at 70% 50%, rgba(196,30,58,.25) 0%, transparent 65%),
        radial-gradient(ellipse at 20% 80%, rgba(27,58,92,.4) 0%, transparent 60%);
    }
    .hero-pattern {
      position: absolute;
      inset: 0;
      background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }
    .hero-content {
      position: relative;
      z-index: 1;
      padding: 80px 0;
    }
    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(196,30,58,.2);
      border: 1px solid rgba(196,30,58,.4);
      color: #f4a0ac;
      font-size: 0.78rem;
      font-weight: 600;
      letter-spacing: .1em;
      text-transform: uppercase;
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 24px;
    }
    .hero-pulse {
      width: 8px; height: 8px;
      background: #f4a0ac;
      border-radius: 50%;
      animation: pulse 2s ease-in-out infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: .5; transform: scale(1.4); }
    }
    .hero h1 {
      font-family: 'Lora', serif;
      font-size: clamp(2.2rem, 5vw, 3.6rem);
      color: #fff;
      line-height: 1.15;
      max-width: 720px;
      margin-bottom: 24px;
    }
    .hero h1 span { color: #f4a0ac; }
    .hero-sub {
      font-size: clamp(1rem, 2vw, 1.15rem);
      color: rgba(255,255,255,.8);
      max-width: 580px;
      line-height: 1.7;
      margin-bottom: 40px;
    }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-trust {
      margin-top: 56px;
      display: flex;
      align-items: center;
      gap: 24px;
      flex-wrap: wrap;
    }
    .hero-trust-item {
      display: flex;
      align-items: center;
      gap: 8px;
      color: rgba(255,255,255,.75);
      font-size: 0.85rem;
    }
    .hero-trust-item svg { flex-shrink: 0; }

    /* ── Mission ── */
    .mission {
      padding: 96px 0;
      background: var(--gray-50);
    }
    .mission-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }
    .mission-image {
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, var(--navy-light) 0%, #d4dde8 100%);
      position: relative;
    }
    .mission-image-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      color: var(--navy);
    }
    .mission-image-placeholder svg { opacity: .4; }
    .mission-image-placeholder p {
      font-size: 0.85rem;
      color: var(--gray-600);
      text-align: center;
      opacity: .7;
      max-width: 160px;
    }
    .mission-principles {
      margin-top: 32px;
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }
    .principle-tag {
      background: var(--navy-light);
      color: var(--navy);
      font-size: 0.8rem;
      font-weight: 600;
      padding: 6px 14px;
      border-radius: 100px;
      border: 1px solid rgba(27,58,92,.15);
    }
    .mission-body {
      font-size: 1.05rem;
      color: var(--gray-600);
      line-height: 1.8;
      margin-bottom: 20px;
    }

    /* ── Impact Stats ── */
    .impact {
      padding: 80px 0;
      background: var(--navy);
    }
    .impact-header {
      text-align: center;
      margin-bottom: 56px;
    }
    .impact-header .section-label { color: #f4a0ac; }
    .impact-header .section-heading { color: #fff; }
    .impact-header .section-subheading { color: rgba(255,255,255,.7); margin: 0 auto; }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2px;
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: rgba(255,255,255,.06);
    }
    .stat-card {
      background: rgba(255,255,255,.04);
      padding: 48px 32px;
      text-align: center;
      transition: background .2s;
    }
    .stat-card:hover { background: rgba(255,255,255,.09); }
    .stat-number {
      font-family: 'Lora', serif;
      font-size: clamp(2.2rem, 4vw, 3.2rem);
      font-weight: 600;
      color: #fff;
      line-height: 1;
      margin-bottom: 8px;
    }
    .stat-number .stat-accent { color: #f4a0ac; }
    .stat-label {
      font-size: 0.9rem;
      color: rgba(255,255,255,.65);
      font-weight: 500;
      text-transform: uppercase;
      letter-spacing: .06em;
    }
    .stat-icon {
      width: 48px;
      height: 48px;
      background: rgba(196,30,58,.25);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      color: #f4a0ac;
    }

    /* ── Programs ── */
    .programs {
      padding: 96px 0;
      background: #fff;
    }
    .programs-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 48px;
    }
    .accordion { display: flex; flex-direction: column; gap: 0; }
    .accordion-item {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius);
      margin-bottom: 8px;
      overflow: hidden;
      transition: box-shadow .2s;
    }
    .accordion-item.active { box-shadow: var(--shadow-md); border-color: rgba(196,30,58,.3); }
    .accordion-trigger {
      width: 100%;
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 20px 24px;
      background: none;
      border: none;
      text-align: left;
      font-size: 1rem;
      font-weight: 600;
      color: var(--gray-800);
      transition: background .15s;
    }
    .accordion-trigger:hover { background: var(--gray-50); }
    .accordion-item.active .accordion-trigger { background: var(--red-light); color: var(--red); }
    .acc-icon {
      width: 40px;
      height: 40px;
      background: var(--navy-light);
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      color: var(--navy);
      font-size: 1.2rem;
      transition: background .2s, color .2s;
    }
    .accordion-item.active .acc-icon { background: rgba(196,30,58,.15); color: var(--red); }
    .acc-label { flex: 1; }
    .acc-chevron {
      width: 20px; height: 20px;
      color: var(--gray-400);
      transition: transform .3s;
      flex-shrink: 0;
    }
    .accordion-item.active .acc-chevron { transform: rotate(180deg); color: var(--red); }
    .accordion-body {
      max-height: 0;
      overflow: hidden;
      transition: max-height .35s ease;
    }
    .accordion-body-inner {
      padding: 0 24px 24px 80px;
    }
    .accordion-body p {
      color: var(--gray-600);
      line-height: 1.75;
      margin-bottom: 16px;
    }
    .acc-learn { color: var(--red); font-weight: 600; font-size: 0.9rem; display: inline-flex; align-items: center; gap: 4px; }
    .acc-learn:hover { text-decoration: underline; }

    /* ── Get Involved ── */
    .get-involved {
      padding: 96px 0;
      background: var(--gray-50);
    }
    .involve-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 28px;
      margin-top: 48px;
    }
    .involve-card {
      background: #fff;
      border-radius: var(--radius-lg);
      padding: 40px 32px;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: transform .2s, box-shadow .2s;
      display: flex;
      flex-direction: column;
    }
    .involve-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .involve-card-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      margin-bottom: 20px;
    }
    .involve-card h3 {
      font-size: 1.15rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 12px;
    }
    .involve-card p {
      color: var(--gray-600);
      font-size: 0.95rem;
      line-height: 1.7;
      flex: 1;
      margin-bottom: 24px;
    }

    /* ── News ── */
    .news {
      padding: 96px 0;
      background: #fff;
    }
    .news-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 24px;
      margin-bottom: 48px;
    }
    .news-carousel-wrapper { position: relative; overflow: hidden; }
    .news-carousel {
      display: flex;
      gap: 28px;
      transition: transform .45s cubic-bezier(.4,0,.2,1);
    }
    .news-card {
      background: #fff;
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      flex: 0 0 calc(33.333% - 19px);
      box-shadow: var(--shadow-sm);
      transition: box-shadow .2s, transform .2s;
    }
    .news-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
    .news-card-img {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2rem;
      color: rgba(255,255,255,.6);
      font-weight: 700;
    }
    .news-card-body { padding: 24px; }
    .news-tag {
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--red);
      margin-bottom: 8px;
    }
    .news-card h3 {
      font-size: 1rem;
      font-weight: 700;
      color: var(--gray-800);
      margin-bottom: 10px;
      line-height: 1.4;
    }
    .news-card p {
      font-size: 0.88rem;
      color: var(--gray-600);
      line-height: 1.65;
      margin-bottom: 16px;
    }
    .news-read-more {
      color: var(--red);
      font-size: 0.875rem;
      font-weight: 600;
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }
    .news-read-more:hover { text-decoration: underline; }
    .carousel-controls {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 32px;
    }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid var(--gray-200);
      background: #fff;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background .15s, border-color .15s, color .15s;
      color: var(--gray-600);
    }
    .carousel-btn:hover:not(:disabled) { background: var(--red); border-color: var(--red); color: #fff; }
    .carousel-btn:disabled { opacity: .35; cursor: not-allowed; }
    .carousel-dots {
      display: flex;
      gap: 6px;
      margin-left: 8px;
    }
    .carousel-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: var(--gray-200);
      border: none;
      cursor: pointer;
      transition: background .2s, transform .2s;
    }
    .carousel-dot.active { background: var(--red); transform: scale(1.3); }

    /* ── Donate CTA ── */
    .donate-cta {
      padding: 96px 0;
      background: linear-gradient(135deg, var(--navy) 0%, #0e1f33 100%);
      position: relative;
      overflow: hidden;
    }
    .donate-cta::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse at 80% 50%, rgba(196,30,58,.2) 0%, transparent 60%);
    }
    .donate-inner {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }
    .donate-text .section-label { color: #f4a0ac; }
    .donate-text .section-heading { color: #fff; }
    .donate-text p { color: rgba(255,255,255,.75); font-size: 1.05rem; line-height: 1.75; margin-bottom: 24px; }
    .efficiency-bar {
      display: flex;
      align-items: center;
      gap: 12px;
      background: rgba(255,255,255,.08);
      padding: 14px 20px;
      border-radius: var(--radius);
      border: 1px solid rgba(255,255,255,.12);
    }
    .efficiency-num {
      font-family: 'Lora', serif;
      font-size: 2rem;
      font-weight: 600;
      color: #7dd3a8;
    }
    .efficiency-text { font-size: 0.85rem; color: rgba(255,255,255,.7); }
    .donate-amounts {
      background: rgba(255,255,255,.06);
      border: 1px solid rgba(255,255,255,.1);
      border-radius: var(--radius-lg);
      padding: 36px;
    }
    .donate-amounts h3 {
      color: #fff;
      font-size: 1.1rem;
      font-weight: 700;
      margin-bottom: 20px;
    }
    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 20px;
    }
    .amount-btn {
      background: rgba(255,255,255,.08);
      border: 1px solid rgba(255,255,255,.2);
      color: #fff;
      border-radius: var(--radius);
      padding: 14px 8px;
      font-size: 0.95rem;
      font-weight: 600;
      transition: background .15s, border-color .15s;
      text-align: center;
      cursor: pointer;
    }
    .amount-btn:hover, .amount-btn.active {
      background: var(--red);
      border-color: var(--red);
    }
    .amount-impact {
      font-size: 0.75rem;
      color: rgba(255,255,255,.55);
      font-weight: 400;
      display: block;
      margin-top: 2px;
    }
    .donate-now-btn {
      width: 100%;
      padding: 16px;
      background: var(--red);
      color: #fff;
      border: none;
      border-radius: var(--radius);
      font-size: 1rem;
      font-weight: 700;
      transition: background .2s;
      margin-top: 8px;
    }
    .donate-now-btn:hover { background: var(--red-dark); }

    /* ── Footer ── */
    .site-footer {
      background: var(--gray-800);
      color: rgba(255,255,255,.75);
      padding: 64px 0 0;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
      gap: 40px;
      padding-bottom: 48px;
      border-bottom: 1px solid rgba(255,255,255,.1);
