    .footer-brand p {
      font-size: 0.88rem;
      line-height: 1.75;
      margin: 16px 0 24px;
      color: rgba(255,255,255,.55);
    }
    .social-links { display: flex; gap: 8px; }
    .social-link {
      width: 36px; height: 36px;
      border-radius: var(--radius);
