    .footer-col a {
      font-size: 0.875rem;
      color: rgba(255,255,255,.65);
      transition: color .15s;
    }
    .footer-col a:hover { color: #fff; }
    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 20px 0;
      font-size: 0.8rem;
      color: rgba(255,255,255,.4);
      flex-wrap: wrap;
    }
    .footer-bottom a { color: rgba(255,255,255,.4); }
    .footer-bottom a:hover { color: rgba(255,255,255,.7); }

    /* ── Donation Modal ── */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,.6);
      backdrop-filter: blur(4px);
      z-index: 1000;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      pointer-events: none;
      transition: opacity .25s;
    }
    .modal-overlay.open { opacity: 1; pointer-events: all; }
    .modal {
      background: #fff;
      border-radius: var(--radius-lg);
      width: 100%;
      max-width: 560px;
      max-height: 90vh;
      overflow-y: auto;
      box-shadow: var(--shadow-lg);
      transform: translateY(20px) scale(.97);
      transition: transform .3s ease;
    }
    .modal-overlay.open .modal { transform: translateY(0) scale(1); }
    .modal-header {
      background: linear-gradient(135deg, var(--navy) 0%, #0e1f33 100%);
      padding: 28px 32px;
      border-radius: var(--radius-lg) var(--radius-lg) 0 0;
      position: relative;
    }
    .modal-header h2 {
      font-family: 'Lora', serif;
      color: #fff;
      font-size: 1.5rem;
      margin-bottom: 6px;
    }
    .modal-header p { color: rgba(255,255,255,.7); font-size: 0.9rem; }
    .modal-close {
      position: absolute;
      top: 16px;
      right: 16px;
      width: 36px; height: 36px;
      background: rgba(255,255,255,.12);
      border: none;
      border-radius: 50%;
      color: rgba(255,255,255,.8);
      font-size: 1.1rem;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background .15s;
    }
    .modal-close:hover { background: rgba(255,255,255,.25); }
    .modal-body { padding: 32px; }
    .modal-amounts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 16px;
    }
    .modal-amount-btn {
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 16px 8px;
      background: #fff;
      cursor: pointer;
      text-align: center;
      transition: border-color .15s, background .15s;
    }
    .modal-amount-btn:hover { border-color: var(--red); background: var(--red-light); }
    .modal-amount-btn.selected { border-color: var(--red); background: var(--red-light); }
    .modal-amount-num { font-size: 1.2rem; font-weight: 700; color: var(--navy); display: block; }
    .modal-amount-impact { font-size: 0.72rem; color: var(--gray-600); display: block; margin-top: 3px; }
    .modal-custom-row {
      margin-bottom: 24px;
    }
    .modal-custom-row label {
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--gray-800);
      display: block;
      margin-bottom: 8px;
    }
    .modal-custom-input {
      width: 100%;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 12px 16px;
      font-size: 1rem;
      font-family: inherit;
      color: var(--gray-800);
      transition: border-color .15s;
      outline: none;
    }
    .modal-custom-input:focus { border-color: var(--red); }
    .modal-freq {
      display: flex;
      gap: 8px;
      margin-bottom: 24px;
    }
    .modal-freq-btn {
      flex: 1;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 10px;
      background: #fff;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--gray-600);
      cursor: pointer;
      transition: all .15s;
    }
    .modal-freq-btn.selected { border-color: var(--navy); background: var(--navy-light); color: var(--navy); }
    .modal-submit {
      width: 100%;
      padding: 16px;
      background: var(--red);
      color: #fff;
      border: none;
      border-radius: var(--radius);
      font-size: 1rem;
      font-weight: 700;
      font-family: inherit;
      transition: background .2s;
      margin-bottom: 12px;
    }
    .modal-submit:hover { background: var(--red-dark); }
    .modal-secure {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      font-size: 0.78rem;
      color: var(--gray-400);
    }

    /* ── Responsive ── */
    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
      .donate-inner { grid-template-columns: 1fr; gap: 40px; }
    }
    @media (max-width: 768px) {
      .main-nav { display: none; }
      .hamburger { display: flex; }
      .mission-grid { grid-template-columns: 1fr; gap: 40px; }
      .mission-image { display: none; }
      .programs-header { flex-direction: column; }
      .involve-grid { grid-template-columns: 1fr; }
      .news-card { flex: 0 0 calc(85vw - 48px); }
      .footer-top { grid-template-columns: 1fr 1fr; gap: 28px; }
      .footer-brand { grid-column: 1 / -1; }
      .utility-bar { display: none; }
      .accordion-body-inner { padding-left: 24px; }
      .modal-amounts { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 480px) {
      .hero-actions { flex-direction: column; }
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .footer-top { grid-template-columns: 1fr; }
      .donate-amounts .amount-grid { grid-template-columns: repeat(2, 1fr); }
    }
  </style>
</head>
